package net.officefloor.hq.app.template;

import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.history.History;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

/** The claim templates per sheet, one per name. */
@Repository
public class TemplateStore {

    private static final RowMapper<Template> ROW = (rs, n) -> new Template(rs.getString("name"),
            rs.getBigDecimal("amount").setScale(2), rs.getString("note"));

    private final JdbcTemplate jdbc;

    public TemplateStore(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's templates, by name. */
    public List<Template> list(String sheetId) {
        return jdbc.query("SELECT name, amount, note FROM claim_template WHERE sheet_id = ? ORDER BY name", ROW, sheetId);
    }

    /** The sheet's templates at the end of the date (see {@link History}), by name. */
    public List<Template> listAsOf(String sheetId, LocalDate date) {
        return jdbc.query("SELECT name, amount, note FROM " + History.asOf("claim_template", "id", date)
                + " WHERE sheet_id = ? ORDER BY name", ROW, sheetId);
    }

    /** The template of that name, as it is now; null when the sheet has none. */
    public Template find(String sheetId, String name) {
        List<Template> found = jdbc.query("SELECT name, amount, note FROM claim_template WHERE sheet_id = ? AND name = ?",
                ROW, sheetId, name);
        return found.isEmpty() ? null : found.get(0);
    }

    /** Saves the template, replacing the amount and note of one already saved under its name. */
    public void save(String sheetId, Template t) {
        if (jdbc.update("UPDATE claim_template SET amount = ?, note = ? WHERE sheet_id = ? AND name = ?",
                t.amount(), t.note(), sheetId, t.name()) == 0) {
            jdbc.update("INSERT INTO claim_template (sheet_id, name, amount, note) VALUES (?, ?, ?, ?)",
                    sheetId, t.name(), t.amount(), t.note());
        }
    }
}
package net.officefloor.hq.app.template;

import java.math.BigDecimal;
import java.util.regex.Pattern;
import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** Refuses a template by a viewer, with a blank name, or with an amount the claim form would refuse for a
 *  claim made from it (one that is not a number with up to two decimals, or a negative one: a template
 *  names no claim to correct). */
public class ValidateTemplate {
    private static final Pattern AMOUNT = Pattern.compile("\\d+(\\.\\d{1,2})?");

    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody TemplateRequest request,
            Out<TemplateInput> body, RoleStore roles) throws InvalidSheetException {
        String user = request == null || request.user() == null ? "" : request.user().trim();
        roles.refuseChange(sheetId.trim(), user);
        String name = request == null || request.name() == null ? "" : request.name().trim();
        if (name.isEmpty()) {
            throw new InvalidSheetException("A template needs a name");
        }
        String amount = request.amount() == null ? "" : request.amount().trim();
        if (!AMOUNT.matcher(amount).matches()) {
            throw new InvalidSheetException("The amount must be a number with up to two decimals");
        }
        String note = request.note() == null ? "" : request.note().trim();
        body.set(new TemplateInput(new Template(name, new BigDecimal(amount).setScale(2), note), user));
    }
}
-- The sheet's claim templates: a name (trimmed, at most once per sheet), the amount and the note a claim
-- made from one starts with. Saving a name again replaces its amount and note; a claim made from a
-- template copies them, so a later change leaves it as it was. Kept by version like the rest of the screen.
CREATE TABLE claim_template (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(255)   NOT NULL,
    name     VARCHAR(1000)  NOT NULL,
    amount   DECIMAL(19, 2) NOT NULL,
    note     VARCHAR(4000)  NOT NULL,
    UNIQUE (sheet_id, name)
);

CREATE TABLE claim_template_hist AS SELECT * FROM claim_template WITH NO DATA;
ALTER TABLE claim_template_hist ADD COLUMN hist_seq BIGINT NOT NULL;
ALTER TABLE claim_template_hist ADD COLUMN hist_made_on DATE NOT NULL;
ALTER TABLE claim_template_hist ADD COLUMN hist_gone BOOLEAN DEFAULT FALSE NOT NULL;
CREATE INDEX claim_template_hist_key ON claim_template_hist (id, hist_seq);
CREATE TRIGGER claim_template_history AFTER INSERT, UPDATE, DELETE ON claim_template FOR EACH ROW
    CALL 'net.officefloor.hq.app.history.HistoryTrigger';
-- A person transferred onto a sheet merges into one already there with their name or an alias, and their
-- name and aliases join that person's even when one equals an alias of theirs in all but case: aliases are
-- no longer unique on a sheet by the index (the app still refuses a new alias that is taken).
DROP INDEX person_alias_sheet_key;
CREATE INDEX person_alias_sheet_key ON person_alias (sheet_id, alias_key);

