import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, postJson } from '../../api/http';
import { PersonColumnHeads, PersonColumns } from '../../slots/defs/personColumns';
import { type Person, peopleKey, personActionKey, useLatestPersonAction } from '../people/people';
import { useCurrentSheet, useCurrentUser } from '../../session/session';

function AliasesHead() {
  return <th>Aliases</th>;
}

// The person's aliases (sorted as names are compared, comma and space separated), and the entry and
// button that add one. The quick-add bar and the paste box find a person by an alias as by their name.
// A refused alias shows its error until the entry is changed or the next action is taken.
function PersonAliases({ person }: { person: Person }) {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const [alias, setAlias] = useState('');
  const queryClient = useQueryClient();

  const add = useMutation({
    mutationKey: personActionKey(sheet, person.id),
    mutationFn: (typed: string) =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/aliases`, { alias: typed, user }),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheet) });
      setAlias('');
    },
  });

  const latest = useLatestPersonAction(sheet, person.id);

  return (
    <td>
      <span data-testid="person-aliases">{person.aliases.join(', ')}</span>
      <input
        data-testid="person-alias-input"
        aria-label="Alias"
        value={alias}
        onChange={(e) => {
          add.reset();
          setAlias(e.target.value);
        }}
      />
      <button
        type="button"
        data-testid="person-alias-add"
        disabled={add.isPending}
        onClick={() => {
          add.reset();
          add.mutate(alias);
        }}
      >
        Add alias
      </button>
      {add.isError && add.submittedAt >= latest && (
        <span data-testid="person-error" role="alert">
          {' '}
          {add.error instanceof HttpError && add.error.reason ? `${add.error.reason}.` : 'The alias was refused.'}
        </span>
      )}
    </td>
  );
}

export const contributions = [
  PersonColumnHeads.fill({ order: 1, Component: AliasesHead }),
  PersonColumns.fill({ order: 1, Component: PersonAliases }),
];
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asOfKey, asOfPath, sheetKey } from '../sheet/sheet';
import { useAsOf } from '../../session/session';

/** A claim template: a claim made from it starts with its amount and note. */
export type Template = { name: string; amount: string; note: string };

/** Under the sheet's key, so loading the sheet again re-reads its templates. */
export const templatesKey = (sheet: string) => [...sheetKey(sheet), 'templates'] as const;

export function useTemplates(sheet: string) {
  const [asOf] = useAsOf();
  return useQuery({
    queryKey: asOfKey(templatesKey(sheet), asOf),
    queryFn: () => getJson<Template[]>(asOfPath(`/api/sheets/${encodeURIComponent(sheet)}/templates`, asOf)),
    enabled: sheet !== '',
  });
}
import { type ChangeEvent, useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { HomeMain } from '../../slots/defs/homeMain';
import { useCurrentSheet, useCurrentUser } from '../../session/session';
import { type Template, templatesKey, useTemplates } from './templates';

type Fields = { name: string; amount: string; note: string };
const EMPTY: Fields = { name: '', amount: '', note: '' };

// The sheet's claim templates, and the form a template is saved with. A blank name, or an amount the
// claim form would refuse, is refused; saving a name again replaces that template.
function Templates() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const templates = useTemplates(sheet);
  const [fields, setFields] = useState<Fields>(EMPTY);
  const queryClient = useQueryClient();

  const save = useMutation({
    mutationFn: (f: Fields) =>
      postJson<Template>(`/api/sheets/${encodeURIComponent(sheet)}/templates`, { ...f, user }),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: templatesKey(sheet) });
      setFields(EMPTY);
    },
  });
  const submit = useSubmitOnce(save);
  const set = (key: keyof Fields) => (e: ChangeEvent<HTMLInputElement>) => {
    setFields({ ...fields, [key]: e.target.value });
    save.reset();
  };

  return (
    <section data-testid="templates">
      <h2>Claim templates</h2>
      <ul>
        {(templates.data ?? []).map((t) => (
          <li key={t.name} data-testid={`template-row-${t.name}`}>
            <span data-testid="template-name">{t.name}</span>{' '}
            <span data-testid="template-amount">{t.amount}</span>{' '}
            <span data-testid="template-note">{t.note}</span>
          </li>
        ))}
      </ul>
      <form
        data-testid="template-form"
        onSubmit={(e) => {
          e.preventDefault();
          submit(fields);
        }}
      >
        <input data-testid="template-form-name" placeholder="Template name" value={fields.name} onChange={set('name')} />
        <input
          data-testid="template-form-amount"
          placeholder="Amount"
          inputMode="decimal"
          value={fields.amount}
          onChange={set('amount')}
        />
        <input data-testid="template-form-note" placeholder="Note" value={fields.note} onChange={set('note')} />
        <button type="submit" data-testid="template-form-submit" disabled={save.isPending}>
          Save template
        </button>
        {save.isError && (
          <span data-testid="template-form-error" role="alert">
            {' '}
            {save.error instanceof HttpError && save.error.reason ? `${save.error.reason}.` : 'The template was refused.'}
          </span>
        )}
      </form>
    </section>
  );
}

export const contribution = HomeMain.fill({ order: 47.6, Component: Templates });
import { defineSlot } from '../Slot';

/** The shell's header: who is signed in and which sheet is active. */
export const AppHeader = defineSlot('app.header');
import { defineSlot } from '../Slot';

/**
 * The shell's nav bar. Every page contributes its own link — the shell never lists the pages.
 * A nav link carries `data-testid="nav-<section>"` (the test contract; CLAUDE.md).
 */
export const AppNav = defineSlot('app.nav');
import { defineSlot } from '../Slot';

/** The home page's body: the sheet's panels (its people, ...). */
export const HomeMain = defineSlot('home.main');
import { defineSlot } from '../Slot';
import type { Person } from '../../features/people/people';

/** Extra header cells of the people table, one per column a feature adds. */
export const PersonColumnHeads = defineSlot('person.columnHeads');

/** Extra cells of a person's row, in the same order as their header cells. */
export const PersonColumns = defineSlot<{ person: Person }>('person.columns');

